"""Generated programs of the FP8 E4M3 paged context attention of the cake_fmha module (head
dim 128, bottom-right causal, the GQA group packed into the M tile), for sm_100a and
sm_103a: B256 (sm_100a) and B256_PX (sm_103a, a 4-stage K/V ring and the P tile in the
other stage's S columns; B256_KV4 for launches of at most 256 keys) take the softmax and
output scales as host scalars, B256_SCALE_PTR, B256_SCALE_PTR_PX and B256_SCALE_PTR_KV4
read them from device scalars; the RUNTIME_PACK programs take the lengths, head counts,
m-block count, page size and scale source as launch arguments (PAGE64: 64-token pages
only; PX: sm_103a, a 4-stage K/V ring and the P tile in the other stage's S columns, the
others on sm_103a for launches of at most 128 keys; Q1: one query stage per tile, for
launches whose tiles hold at most one stage of query tokens, the every-page-size ones
also on sm_103a for launches of at most 128 keys; MW: without the short-KV chain, for
sm_100a launches of many tiles over few keys; OW: stage 0 stored as soon as its last PV
is in, or for a Q1 program the short-KV chain, for sm_100a launches of one tile per CTA;
NC, LSE, SINK, NC_LSE, NC_SINK: the non-causal, LSE and attention-sink forms, for every
page size and both targets, with PX and PX_Q1 ones for both targets); the RUNTIME_SK
programs are the same schedule with the key range of a tile split over several work
units, whose FP32 partials the tile's last unit merges (S2: two units per split tile at
most, the merging unit's own term from its TMEM O, for sm_100a). The host module
``flashinfer.cake_fmha`` selects the program from the head counts, the page size, the
planned maximum lengths and the kind of scale arguments of a launch, computes the grid
and launches it; other shapes keep the module's other context routes.

Generated file: every value below is derived from the exported sources and checked
against them; do not edit.
"""

